    for (let a = 0; a < 24; a++) { const an = a / 24 * Math.PI * 2; const y = Math.round(14 + Math.sin(an) * 8), z = Math.round(111 + Math.cos(an) * 8); b.box(47, y, z, 49, y, z, M_.DARKWOOD); }
