const WEAPON_IDS = Object.keys(WEAPONS);
const PROJ_TYPES = ['frag', 'molotov', 'c4', 'rocket', 'bomb', 'shell', 'gl'];

// ---- server ----
// FRACTURE dedicated server: lobbies + authoritative matches over WebSocket.
// Run: PORT=7778 node server.js      (LAG=ms simulates latency for testing)
const http = require('http');
