const PORT = +(process.env.PORT || 7778);
const LAG = +(process.env.LAG || 0);
const MAX_LOBBY = 12;
let nextId = 1;
const clients = new Map(); // id -> client
const lobbies = new Map(); // code -> lobby
function log(...a) { console.log(new Date().toISOString().slice(11, 19), ...a); }
function code4() { const A = 'ABCDEFGHJKLMNPQRSTUVWXYZ'; let s; do { s = ''; for (let k = 0; k < 4; k++) s += A[(Math.random() * A.length) | 0]; } while (lobbies.has(s)); return s; }
function sendRaw(c, str) { if (c.ws.readyState !== 1) return; if (LAG) setTimeout(() => c.ws.readyState === 1 && c.ws.send(str), LAG / 2); else c.ws.send(str); }
