  const M = MODES[o.mode] || MODES.tdm;
  const net = {
    send: (id, m) => { const c = clients.get(id); if (c && c.inMatch) send(c, m); },
    broadcast: m => { const s = JSON.stringify(m); for (const c of L.members.values()) if (c.inMatch) sendRaw(c, s); },
  };
